// Build configuration from environment variables
const repo = $env.GITHUB_REPO || 'claude-builders-bounty/claude-builders-bounty';
const lang = $env.SUMMARY_LANGUAGE || 'EN';
const githubToken = $env.GITHUB_TOKEN || '';
const claudeApiKey = $env.ANTHROPIC_API_KEY || '';
const webhookUrl = $env.DESTINATION_WEBHOOK_URL || '';
const discordWebhook = $env.DISCORD_WEBHOOK_URL || '';
const slackWebhook = $env.SLACK_WEBHOOK_URL || '';
const emailTo = $env.SUMMARY_EMAIL_TO || '';
const emailFrom = $env.SUMMARY_EMAIL_FROM || 'dev-summary@n8n.local';
const smtpHost = $env.SMTP_HOST || '';
const smtpPort = parseInt($env.SMTP_PORT || '587', 10);
const smtpUser = $env.SMTP_USER || '';
const smtpPass = $env.SMTP_PASS || '';

// Calculate date range (last 7 days)
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const since = weekAgo.toISOString().split('T')[0];
const until = now.toISOString().split('T')[0];

// Determine delivery method (priority: discord > slack > email > local)
let deliveryMethod = 'local';
if (discordWebhook) deliveryMethod = 'discord';
else if (slackWebhook) deliveryMethod = 'slack';
else if (webhookUrl) deliveryMethod = 'webhook';
else if (emailTo && smtpHost) deliveryMethod = 'email';

return [{
  json: {
    repo,
    owner: repo.split('/')[0],
    name: repo.split('/')[1],
    lang,
    githubToken,
    claudeApiKey,
    webhookUrl,
    discordWebhook,
    slackWebhook,
    emailTo,
    emailFrom,
    smtpHost,
    smtpPort,
    smtpUser,
    smtpPass,
    deliveryMethod,
    since,
    until,
    dateRange: `${since} → ${until}`
  }
}];

// Aggregate all fetched data into a unified structure
const config = $items('Build Config')[0].json;

// Process commits
const commitsRaw = $items('Fetch Commits');
const commits = commitsRaw
  .filter(item => item.json && Array.isArray(item.json))
  .flatMap(item => item.json)
  .filter(c => c && c.sha)
  .map(c => ({
    sha: c.sha.substring(0, 7),
    message: (c.commit.message || '').split('\n')[0],
    author: c.commit?.author?.name || 'unknown',
    date: c.commit?.author?.date?.split('T')[0] || ''
  }));

// Process closed issues (filter out PRs — GitHub API returns PRs in issues endpoint)
const issuesRaw = $items('Fetch Closed Issues');
const closedIssues = issuesRaw
  .filter(item => item.json && Array.isArray(item.json))
  .flatMap(item => item.json)
  .filter(i => i && !i.pull_request && i.closed_at)
  .filter(i => {
    const closedDate = new Date(i.closed_at);
    const sinceDate = new Date(config.since);
    return closedDate >= sinceDate;
  })
  .map(i => ({
    number: i.number,
    title: i.title,
    labels: (i.labels || []).map(l => l.name),
    closed_at: i.closed_at?.split('T')[0] || ''
  }));

// Process merged PRs (only those merged within the date range)
const prsRaw = $items('Fetch Merged PRs');
const mergedPRs = prsRaw
  .filter(item => item.json && Array.isArray(item.json))
  .flatMap(item => item.json)
  .filter(p => p && p.merged_at)
  .filter(p => {
    const mergedDate = new Date(p.merged_at);
    const sinceDate = new Date(config.since);
    return mergedDate >= sinceDate;
  })
  .map(p => ({
    number: p.number,
    title: p.title,
    author: p.user?.login || 'unknown',
    merged_at: p.merged_at?.split('T')[0] || '',
    additions: p.additions || 0,
    deletions: p.deletions || 0,
    changed_files: p.changed_files || 0
  }));

// Build summary stats
const stats = {
  commits: commits.length,
  closedIssues: closedIssues.length,
  mergedPRs: mergedPRs.length,
  uniqueAuthors: [...new Set(commits.map(c => c.author))].length,
  totalAdditions: mergedPRs.reduce((sum, p) => sum + p.additions, 0),
  totalDeletions: mergedPRs.reduce((sum, p) => sum + p.deletions, 0)
};

return [{
  json: {
    ...config,
    commits,
    closedIssues,
    mergedPRs,
    stats,
    commitsText: commits.map(c => `- ${c.sha} ${c.message} (${c.author}, ${c.date})`).join('\n'),
    issuesText: closedIssues.map(i => `- #${i.number} ${i.title} [${i.labels.join(', ')}] (${i.closed_at})`).join('\n'),
    prsText: mergedPRs.map(p => `- #${p.number} ${p.title} by @${p.author} (+${p.additions}/-${p.deletions}, ${p.changed_files} files, ${p.merged_at})`).join('\n')
  }
}];

const data = $json;

const langInstruction = data.lang === 'FR'
  ? 'Rédige le résumé en français.'
  : 'Write the summary in English.';

const prompt = `You are a senior engineering manager writing a weekly dev summary for the GitHub repository ${data.repo}.

## Week: ${data.dateRange}

## Stats
- ${data.stats.commits} commits by ${data.stats.uniqueAuthors} authors
- ${data.stats.mergedPRs} merged PRs (+${data.stats.totalAdditions}/-${data.stats.totalDeletions} lines)
- ${data.stats.closedIssues} closed issues

## Commits
${data.commitsText || '(none)'}

## Closed Issues
${data.issuesText || '(none)'}

## Merged PRs
${data.prsText || '(none)'}

## Instructions
${langInstruction}

Write a concise, well-structured weekly summary with:
1. **Highlights** — Key accomplishments this week (2-4 bullet points)
2. **Merged PRs** — Summarize each PR in one sentence, grouped by theme if possible
3. **Closed Issues** — Brief summary of resolved issues
4. **Activity Overview** — ${data.stats.commits} commits, ${data.stats.mergedPRs} PRs merged, ${data.stats.closedIssues} issues closed
5. **Looking Ahead** — Suggest areas of focus for next week based on this week's activity

Format in Markdown. Keep it under 400 words.`;

return [{ json: { ...data, prompt } }];

// Extract Claude's response and format for all delivery channels
const response = $json;
const config = $items('Build Config')[0].json;

let summaryText = '';
if (response.content && Array.isArray(response.content)) {
  summaryText = response.content
    .filter(block => block.type === 'text')
    .map(block => block.text)
    .join('\n');
} else if (typeof response.body === 'object' && response.body?.content) {
  summaryText = response.body.content
    .filter(block => block.type === 'text')
    .map(block => block.text)
    .join('\n');
} else {
  summaryText = JSON.stringify(response);
}

const header = `📊 **Weekly Dev Summary: ${config.repo}**\n🗓 ${config.dateRange}\n---\n\n`;
const footer = `\n---\n_Generated by n8n + Claude_`;

const fullSummary = header + summaryText + footer;
const markdownSummary = summaryText;

return [{
  json: {
    fullSummary,
    markdownSummary,
    header,
    deliveryMethod: config.deliveryMethod,
    webhookUrl: config.webhookUrl,
    discordWebhook: config.discordWebhook,
    slackWebhook: config.slackWebhook,
    emailTo: config.emailTo,
    emailFrom: config.emailFrom,
    smtpHost: config.smtpHost,
    smtpPort: config.smtpPort,
    smtpUser: config.smtpUser,
    smtpPass: config.smtpPass,
    repo: config.repo,
    dateRange: config.dateRange,
    stats: $items('Aggregate Data')[0].json.stats
  }
}];

// Local fallback: log summary and return as workflow output
console.log($json.fullSummary);
return [{
  json: {
    success: true,
    deliveryMethod: 'local',
    repo: $json.repo,
    dateRange: $json.dateRange,
    summary: $json.fullSummary,
    stats: $json.stats
  }
}];
